package ru.kstolu.app;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import android.view.*;import android.widget.*;import android.graphics.*;import org.json.*;import java.lang.reflect.*;import java.io.*;import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class RedesignTest {
    private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity activity;private AtomicInteger calls;
    private JSONObject recipe()throws Exception{return new JSONObject("{\"status\":\"ok\",\"title\":\"Тосты с авокадо и творожным сыром\",\"description\":\"Хрустящий хлеб, нежный сыр и спелый авокадо.\",\"image_prompt\":\"Open-faced wholegrain bread sandwiches spread with white cream cheese and topped with slices of green avocado.\",\"servings\":2,\"nutrition\":{\"source\":\"estimate\",\"kcal_per_serving\":322},\"prep_minutes\":10,\"cook_minutes\":0,\"ingredients\":[{\"name\":\"Хлеб цельнозерновой\",\"amount\":80,\"unit\":\"g\",\"price\":null},{\"name\":\"Авокадо\",\"amount\":1,\"unit\":\"piece\",\"price\":null},{\"name\":\"Творожный сыр\",\"amount\":60,\"unit\":\"g\",\"price\":null}],\"steps\":[{\"title\":\"Соберите тосты\",\"body\":\"Подсушите хлеб. Намажьте сыром и выложите ломтики авокадо.\"}],\"warnings\":[]}");}
    private JSONObject snapshot()throws Exception{return new JSONObject().put("recipe",recipe()).put("currency","RUB");}
    private Object invoke(String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}
    private void set(String name,Object value)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
    private TextView find(View view,String label){if(view instanceof TextView&&((TextView)view).getText().toString().equals(label))return (TextView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++){TextView result=find(group.getChildAt(n),label);if(result!=null)return result;}}return null;}
    private TextView find(String label){return find(activity.getWindow().getDecorView(),label);}
    private void click(String label){assertNotNull(label,find(label));find(label).performClick();}
    private void render(String name,int width,int height)throws Exception{View root=activity.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));root.layout(0,0,width,height);Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap));File dir=new File("build/visual-qa");dir.mkdirs();try(FileOutputStream stream=new FileOutputStream(new File(dir,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
    @Before public void setup(){controller=Robolectric.buildActivity(MainActivity.class).setup();activity=controller.get();calls=new AtomicInteger();ApiClient.configureForTests(null,url->{calls.incrementAndGet();throw new IOException("No network in visual tests");});}
    @After public void close(){controller.pause().stop().destroy();ApiClient.restoreTransport();}
    @Test public void photoButtonAlwaysVisibleButEnablingAndGenerationRequireSeparateConsent()throws Exception{
        set("authenticated",true);invoke("openRecipe",new Class[]{JSONObject.class,String.class},snapshot(),"choices");assertNotNull(find("Сгенерировать фото"));assertEquals(0,calls.get());click("Сгенерировать фото");android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);assertEquals("Включить генерацию фото?",org.robolectric.Shadows.shadowOf(dialog).getTitle());assertEquals(0,calls.get());dialog.getButton(android.content.DialogInterface.BUTTON_NEGATIVE).performClick();assertFalse(activity.getSharedPreferences("settings",0).getBoolean("generation",false));
        click("Сгенерировать фото");dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialog.getButton(android.content.DialogInterface.BUTTON_POSITIVE).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(activity.getSharedPreferences("settings",0).getBoolean("generation",false));android.app.AlertDialog confirm=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Создать одно фото блюда?",org.robolectric.Shadows.shadowOf(confirm).getTitle());assertEquals(0,calls.get());confirm.getButton(android.content.DialogInterface.BUTTON_NEGATIVE).performClick();
    }
    @Test public void caloriesPerServingDoNotDoubleWithPortionStepperAndSurviveHistory()throws Exception{
        JSONObject item=snapshot();invoke("openRecipe",new Class[]{JSONObject.class,String.class},item,"choices");assertNotNull(find("≈ 320"));click("+");assertNotNull(find("≈ 320"));assertNotNull(find("90 г"));click("Сохранить рецепт");click("Сохранённое");assertNotNull(find("10 мин · ≈ 320 ккал / порция"));assertTrue(new File(activity.getFilesDir(),"history.json").isFile());String history=new String(java.nio.file.Files.readAllBytes(new File(activity.getFilesDir(),"history.json").toPath()),java.nio.charset.StandardCharsets.UTF_8);assertTrue(history.contains("kcal_per_serving"));assertEquals(0,calls.get());
    }
    @Test public void selectedDesignHasNativeFullWidthScreensAndRecipeStats()throws Exception{
        set("choices",new JSONArray().put(snapshot()));invoke("home",new Class[]{});assertNotNull(find("К столу"));render("08-olive-home",390,844);invoke("showChoices",new Class[]{});render("09-olive-choices",390,844);invoke("openRecipe",new Class[]{JSONObject.class,String.class},snapshot(),"choices");render("10-olive-recipe",390,844);assertNotNull(find("Сгенерировать фото"));assertNotNull(find("ккал / порция"));assertNotNull(find("Нет цены"));render("11-olive-wide",820,900);render("12-olive-landscape",844,390);assertEquals(0,calls.get());
    }
    @Test public void oldAndInvalidCaloriesAreNeverShownAsZero()throws Exception{
        JSONObject r=recipe();r.remove("nutrition");assertEquals("Ккал пока неизвестны",Calories.label(r));for(Object value:new Object[]{0,-1,5001,"320",Double.NaN}){JSONObject n=new JSONObject().put("source","estimate");if(value instanceof Double&&Double.isNaN((Double)value))continue;n.put("kcal_per_serving",value);r.put("nutrition",n);assertEquals(-1,Calories.value(r));}r.put("nutrition",new JSONObject().put("source","estimate").put("kcal_per_serving",322));assertEquals(320,Calories.value(r));
    }
}
